def create_task(user_id, title, description=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0310000" if __import__("os").path.isdir("./environment_mix/0310000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "create_task"

    def _normalize_db(raw):
        # Store may be [], {} or other; normalize to a dict with users/tasks plus audit log.
        db = raw if isinstance(raw, dict) else {}
        users = db.get("users")
        tasks = db.get("tasks")
        if not isinstance(users, dict):
            users = {}
        if not isinstance(tasks, dict):
            tasks = {}
        audit = db.get("_audit_log")
        if not isinstance(audit, list):
            audit = []
        rate = db.get("_rate_limits")
        if not isinstance(rate, dict):
            rate = {}
        if "requests_per_minute" not in rate or not isinstance(rate.get("requests_per_minute"), int):
            rate["requests_per_minute"] = 120
        if "requests_per_day" not in rate or not isinstance(rate.get("requests_per_day"), int):
            rate["requests_per_day"] = 5000
        db["users"] = users
        db["tasks"] = tasks
        db["_audit_log"] = audit
        db["_rate_limits"] = rate
        if "_counters" not in db or not isinstance(db.get("_counters"), dict):
            db["_counters"] = {"total_requests": 0, "total_errors": 0}
        return db

    def _prune_old(audit_rows, now_dt):
        # Keep last 7 days for size control; safe even if timestamps are malformed.
        cutoff = now_dt - datetime.timedelta(days=7)
        kept = []
        for r in audit_rows:
            try:
                rts = r.get("timestamp")
                if isinstance(rts, str) and rts.endswith("Z"):
                    rdt = datetime.datetime.fromisoformat(rts[:-1])
                    if rdt >= cutoff:
                        kept.append(r)
                else:
                    kept.append(r)
            except Exception:
                kept.append(r)
        return kept

    def _check_rate_and_log(db, status, error_code=None, error_message=None, details=None):
        # Enforce simplistic global rate limits from audit log.
        now = datetime.datetime.utcnow()
        audit = db["_audit_log"]
        rpm = db["_rate_limits"]["requests_per_minute"]
        rpd = db["_rate_limits"]["requests_per_day"]

        # Count recent requests (all endpoints) in rolling windows.
        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in audit:
            try:
                rts = r.get("timestamp")
                if not (isinstance(rts, str) and rts.endswith("Z")):
                    continue
                rdt = datetime.datetime.fromisoformat(rts[:-1])
                if rdt >= one_min_ago:
                    c_min += 1
                if rdt >= one_day_ago:
                    c_day += 1
            except Exception:
                continue

        # If we are about to return success, rate limit must be checked before logging this request.
        # For errors, still enforce rate limit (real backends often do).
        if c_min >= rpm:
            # log the rate-limited request
            row = {
                "timestamp": ts,
                "endpoint": endpoint,
                "status": "error",
                "error_code": "RATE_LIMIT",
                "message": "Rate limit exceeded (per-minute).",
                "latency_ms": int((time.time() - t0) * 1000),
            }
            audit.append(row)
            db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1
            db["_audit_log"] = _prune_old(audit, now)
            _save("mock_db.json", db)
            return _err("RATE_LIMIT", "Rate limit exceeded (per-minute).", limit=rpm, window_seconds=60)
        if c_day >= rpd:
            row = {
                "timestamp": ts,
                "endpoint": endpoint,
                "status": "error",
                "error_code": "QUOTA_EXCEEDED",
                "message": "Daily request quota exceeded.",
                "latency_ms": int((time.time() - t0) * 1000),
            }
            audit.append(row)
            db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1
            db["_audit_log"] = _prune_old(audit, now)
            _save("mock_db.json", db)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, window_seconds=86400)

        row = {
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if status != "ok":
            row["error_code"] = error_code
            row["message"] = error_message
            if details is not None:
                row["details"] = details
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1
        audit.append(row)
        db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
        db["_audit_log"] = _prune_old(audit, now)
        _save("mock_db.json", db)
        return None

    # Load + normalize
    raw = _load("mock_db.json")
    db = _normalize_db(raw)

    # Validate inputs
    if not isinstance(user_id, str) or not user_id.strip():
        rl = _check_rate_and_log(db, "error", "VALIDATION_ERROR", "user_id is required and must be a non-empty string.")
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "user_id is required and must be a non-empty string.")
    if not isinstance(title, str) or not title.strip():
        rl = _check_rate_and_log(db, "error", "VALIDATION_ERROR", "title is required and must be a non-empty string.")
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "title is required and must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        rl = _check_rate_and_log(db, "error", "VALIDATION_ERROR", "description must be a string when provided.")
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "description must be a string when provided.")

    uid = user_id.strip()
    ttl = title.strip()
    desc = description if description is None else description

    # Must reference existing user
    user = db["users"].get(uid)
    if not isinstance(user, dict):
        rl = _check_rate_and_log(db, "error", "NOT_FOUND", "Referenced user_id does not exist.", user_id=uid)
        if rl:
            return rl
        return _err("NOT_FOUND", "Referenced user_id does not exist.", user_id=uid)

    # Ensure user's tasks list exists
    if "tasks" not in user or not isinstance(user.get("tasks"), list):
        user["tasks"] = []

    # Generate unique task_id
    existing = set(db["tasks"].keys())
    n = len(existing) + 1
    while True:
        task_id = f"task_{n}"
        if task_id not in existing:
            break
        n += 1

    task = {"task_id": task_id, "title": ttl, "description": desc, "status": "pending"}
    db["tasks"][task_id] = task
    user["tasks"].append(task_id)
    db["users"][uid] = user

    # Log and persist (must persist mutation + audit)
    rl = _check_rate_and_log(db, "ok")
    if rl:
        return rl

    return {"task": task}

