def update_task_status(task_id, status, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0310000" if __import__("os").path.isdir("./environment_mix/0310000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "update_task_status"

    def _normalize_db(raw):
        db = raw if isinstance(raw, dict) else {}
        users = db.get("users")
        tasks = db.get("tasks")
        if not isinstance(users, dict):
            users = {}
        if not isinstance(tasks, dict):
            tasks = {}
        audit = db.get("_audit_log")
        if not isinstance(audit, list):
            audit = []
        rate = db.get("_rate_limits")
        if not isinstance(rate, dict):
            rate = {}
        if "requests_per_minute" not in rate or not isinstance(rate.get("requests_per_minute"), int):
            rate["requests_per_minute"] = 120
        if "requests_per_day" not in rate or not isinstance(rate.get("requests_per_day"), int):
            rate["requests_per_day"] = 5000
        db["users"] = users
        db["tasks"] = tasks
        db["_audit_log"] = audit
        db["_rate_limits"] = rate
        if "_counters" not in db or not isinstance(db.get("_counters"), dict):
            db["_counters"] = {"total_requests": 0, "total_errors": 0}
        return db

    def _prune_old(audit_rows, now_dt):
        cutoff = now_dt - datetime.timedelta(days=7)
        kept = []
        for r in audit_rows:
            try:
                rts = r.get("timestamp")
                if isinstance(rts, str) and rts.endswith("Z"):
                    rdt = datetime.datetime.fromisoformat(rts[:-1])
                    if rdt >= cutoff:
                        kept.append(r)
                else:
                    kept.append(r)
            except Exception:
                kept.append(r)
        return kept

    def _check_rate_and_log(db, status_str, error_code=None, error_message=None, details=None):
        now = datetime.datetime.utcnow()
        audit = db["_audit_log"]
        rpm = db["_rate_limits"]["requests_per_minute"]
        rpd = db["_rate_limits"]["requests_per_day"]

        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)
        c_min = 0
        c_day = 0
        for r in audit:
            try:
                rts = r.get("timestamp")
                if not (isinstance(rts, str) and rts.endswith("Z")):
                    continue
                rdt = datetime.datetime.fromisoformat(rts[:-1])
                if rdt >= one_min_ago:
                    c_min += 1
                if rdt >= one_day_ago:
                    c_day += 1
            except Exception:
                continue

        if c_min >= rpm:
            row = {
                "timestamp": ts,
                "endpoint": endpoint,
                "status": "error",
                "error_code": "RATE_LIMIT",
                "message": "Rate limit exceeded (per-minute).",
                "latency_ms": int((time.time() - t0) * 1000),
            }
            audit.append(row)
            db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1
            db["_audit_log"] = _prune_old(audit, now)
            _save("mock_db.json", db)
            return _err("RATE_LIMIT", "Rate limit exceeded (per-minute).", limit=rpm, window_seconds=60)

        if c_day >= rpd:
            row = {
                "timestamp": ts,
                "endpoint": endpoint,
                "status": "error",
                "error_code": "QUOTA_EXCEEDED",
                "message": "Daily request quota exceeded.",
                "latency_ms": int((time.time() - t0) * 1000),
            }
            audit.append(row)
            db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1
            db["_audit_log"] = _prune_old(audit, now)
            _save("mock_db.json", db)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, window_seconds=86400)

        row = {
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status_str,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if status_str != "ok":
            row["error_code"] = error_code
            row["message"] = error_message
            if details is not None:
                row["details"] = details
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1
        audit.append(row)
        db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
        db["_audit_log"] = _prune_old(audit, now)
        _save("mock_db.json", db)
        return None

    raw = _load("mock_db.json")
    db = _normalize_db(raw)

    # Validate inputs
    if not isinstance(task_id, str) or not task_id.strip():
        rl = _check_rate_and_log(db, "error", "VALIDATION_ERROR", "task_id is required and must be a non-empty string.")
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "task_id is required and must be a non-empty string.")
    if not isinstance(status, str) or status not in ("pending", "completed"):
        rl = _check_rate_and_log(db, "error", "VALIDATION_ERROR", "status must be one of: pending, completed.")
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "status must be one of: pending, completed.", allowed=["pending", "completed"])

    tid = task_id.strip()

    # Find task
    task = db["tasks"].get(tid)
    if not isinstance(task, dict):
        rl = _check_rate_and_log(db, "error", "NOT_FOUND", "Task not found.", task_id=tid)
        if rl:
            return rl
        return _err("NOT_FOUND", "Task not found.", task_id=tid)

    # Permission check: ambient auth; pick any consistent "caller" that owns the task.
    # If no user owns it, treat as unauthorized (cannot establish permission context).
    owner_id = None
    for uid, u in db["users"].items():
        if isinstance(u, dict) and isinstance(u.get("tasks"), list) and tid in u.get("tasks"):
            owner_id = uid
            break
    if owner_id is None:
        rl = _check_rate_and_log(db, "error", "UNAUTHORIZED", "Caller does not have permission to modify that task.")
        if rl:
            return rl
        return _err("UNAUTHORIZED", "Caller does not have permission to modify that task.")

    # Apply update (idempotent allowed, but still a real write with audit log persisted)
    task["status"] = status
    db["tasks"][tid] = task

    rl = _check_rate_and_log(db, "ok")
    if rl:
        return rl

    return {"task": task}

def transfer_to_human_agents(summary, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0310000" if __import__("os").path.isdir("./environment_mix/0310000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "transfer_to_human_agents"
    now_dt = datetime.datetime.utcnow()
    ts = now_dt.replace(microsecond=0).isoformat() + "Z"

    # ---- datastore normalize (mock_db.json may be [] in this benchmark) ----
    raw = _load("mock_db.json")
    if isinstance(raw, dict):
        db = raw
    else:
        db = {}

    audit = db.get("_audit_log")
    if not isinstance(audit, list):
        audit = []
    db["_audit_log"] = audit

    rate = db.get("_rate_limits")
    if not isinstance(rate, dict):
        rate = {}
    if not isinstance(rate.get("requests_per_minute"), int) or rate.get("requests_per_minute") <= 0:
        rate["requests_per_minute"] = 120
    if not isinstance(rate.get("requests_per_day"), int) or rate.get("requests_per_day") <= 0:
        rate["requests_per_day"] = 5000
    db["_rate_limits"] = rate

    counters = db.get("_counters")
    if not isinstance(counters, dict):
        counters = {"total_requests": 0, "total_errors": 0}
    if not isinstance(counters.get("total_requests"), int):
        counters["total_requests"] = 0
    if not isinstance(counters.get("total_errors"), int):
        counters["total_errors"] = 0
    db["_counters"] = counters

    # ---- helpers ----
    def _parse_ts(s):
        if isinstance(s, str) and s.endswith("Z"):
            try:
                return datetime.datetime.fromisoformat(s[:-1])
            except ValueError:
                return None
        return None

    def _prune_old(audit_rows, now_dt_local):
        cutoff = now_dt_local - datetime.timedelta(days=7)
        kept = []
        for r in audit_rows:
            rdt = _parse_ts(r.get("timestamp"))
            if rdt is None or rdt >= cutoff:
                kept.append(r)
        return kept

    def _count_in_windows(audit_rows, now_dt_local):
        minute_ago = now_dt_local - datetime.timedelta(minutes=1)
        day_ago = now_dt_local - datetime.timedelta(days=1)
        per_minute = 0
        per_day = 0
        for r in audit_rows:
            rdt = _parse_ts(r.get("timestamp"))
            if rdt is None:
                continue
            if rdt >= day_ago:
                per_day += 1
                if rdt >= minute_ago:
                    per_minute += 1
        return per_minute, per_day

    def _log_and_persist(status, error_obj=None):
        db["_audit_log"] = _prune_old(db["_audit_log"], now_dt)
        rpm_used, rpd_used = _count_in_windows(db["_audit_log"], now_dt)

        latency_ms = int(max(0.0, (time.time() - t0)) * 1000)
        row = {
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
        }
        if error_obj:
            row["error"] = error_obj.get("error", error_obj)
        db["_audit_log"].append(row)

        db["_counters"]["total_requests"] = int(db["_counters"].get("total_requests", 0)) + 1
        if status != "success":
            db["_counters"]["total_errors"] = int(db["_counters"].get("total_errors", 0)) + 1

        _save("mock_db.json", db)

    # ---- rate/quota enforcement (based on prior log rows) ----
    # Count existing calls in windows BEFORE this one is appended.
    db["_audit_log"] = _prune_old(db["_audit_log"], now_dt)
    rpm_used, rpd_used = _count_in_windows(db["_audit_log"], now_dt)
    if rpm_used >= db["_rate_limits"]["requests_per_minute"]:
        err = _err("RATE_LIMIT", "Rate limit exceeded (requests_per_minute).")
        _log_and_persist("error", err)
        return err
    if rpd_used >= db["_rate_limits"]["requests_per_day"]:
        err = _err("QUOTA_EXCEEDED", "Daily quota exceeded (requests_per_day).")
        _log_and_persist("error", err)
        return err

    # ---- input validation ----
    if not isinstance(summary, str):
        err = _err("VALIDATION_ERROR", "summary must be a string.", field="summary")
        _log_and_persist("error", err)
        return err

    cleaned = " ".join(summary.strip().split())
    if not cleaned or len(cleaned) < 10:
        err = _err("VALIDATION_ERROR", "summary is required and must be sufficiently informative for handoff.", field="summary")
        _log_and_persist("error", err)
        return err

    # ---- policy gating (no conversation context provided -> refuse escalation) ----
    # The tool requires: user explicitly asked for a human OR the issue cannot be handled with tools/policies.
    # With only `summary` available, we cannot verify these prerequisites; default to refusal.
    err = _err(
        "UNAUTHORIZED",
        "Escalation refused: no evidence the user requested a human agent, and no indication the issue cannot be handled with available tools/policy guidance.",
        reason="missing_prerequisites",
    )
    _log_and_persist("error", err)
    return err
